import {mapGetters} from "vuex";
import {getInspectionDetailList} from "@/api/xcnanr/statisticalAnalysis"

export default {
  name: 'AccessControl',
  components: {},
  computed: {
    ...mapGetters(["permission", 'userDetail'])
  },
  data() {
    return {
      workOrderParams: {
        isShow: false,
        type: null,
        formDetial: {}
      },
      selectionList: [],
      searchForm: {
        current: 1,
        size: 10,
        statId: null,
        objectName: null
      },
      total: 0,
      searchId: null,
      tableData: [],
      tableHeight: undefined,
      tableLoading: false,
      roomData: null,
      roomAcVersionList:[],
      roomAcBrandList:[],
      roomDescription: null,
      companyId: null,
      companyName: null
    }
  },
  created() {
    this.searchId = this.$route.query.id
    this.companyId = this.$route.query.companyId
    this.companyName = this.$route.query.companyName
    this.month = this.$route.query.month
    this.getList()
  },
  mounted() {
    this.setPageContentHeight();
    this.setTableHeight();
  },
  methods: {
    refreshData(){
      this.getList()
    },
    selectionChange(selection) {
      //点击选择事件
      this.selectionList = selection.map(item => item.id);
    },
    handleQuery() {
      this.searchForm.current = 1;
      this.getList();
    },
    handleReset() {
      this.searchForm.objectName = undefined;
      this.getList();
    },
    // 设置表格高度
    setTableHeight() {
      let bodyBox = document.getElementsByClassName('page_body');
      this.tableHeight = (bodyBox[0].offsetHeight - 100) + 'px'
    },
    getList() {
      this.searchForm.statId = this.searchId
      this.tableLoading = true;
      getInspectionDetailList(this.searchForm).then(res => {
        this.tableData = res.data;
        this.total = res.data.total;
        this.tableLoading = false
      }).catch(() => {
        this.tableLoading = false
      })
    },
    handleSee(row) {
      let queryInfo = {
        inspectionMonth: this.month,
        companyId: this.companyId,
        companyName: this.companyName,
        deptName: '',
        objectId: row.objectId,
        objectName: row.objectName,
        type: row.type
      }
      // queryInfo = {
      //   inspectionMonth: '2024-12',
      //   companyId: '1745022609004736513',
      //   companyName: '国网山东省电力公司',
      //   deptName: '',
      //   objectId: '217809d2048f42e8b1a3da60a895d23e',
      //   objectName: '历城区中心机房',
      //   type: 1
      // }
      this.$router.push({
        path: '/xcnanr/inspectReport/',
        query: queryInfo
      })
    }
  }
}
